    [12522]={name="Bingles' Flying Gloves",quality=2,ilvl=15,reqLevel=12,sourceType="quest_reward",instructions="Reward from the quest 'Bingles' Missing Supplies'. Starts with Bingles Blastenheimer in Loch Modan. Objective: Find and return Bingles' supplies:Bingles' Wrench, Bingles' Screwdriver, Bingles' Hammer, and Bingles' Blastencapper.",zone="Loch Modan",questName="Bingles' Missing Supplies",lore="As if crashing into the Loch wasn't bad enough, troggs from the nearby island attacked me and stole my tools and special Blastenheimer Blastencapper explosives."},
    [12531]={name="Searing Needle",quality=3,ilvl=51,reqLevel=46,sourceType="world_drop",instructions="World drop around level 48-56.",proc="Chance on hit: Blasts a target for 56 Fire damage and increases Fire damage done to target by 10 for 30 sec."},
    [12535]={name="Doomforged Straightedge",quality=3,ilvl=54,reqLevel=49,sourceType="world_drop",instructions="World drop around level 48-56."},
    [12544]={name="Thrall's Resolve",quality=3,ilvl=60,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'The Princess Saved?'. Pick it over the other reward choices.",zone="Blackrock Depths",questName="The Princess Saved?",lore="You have slain my husband! My child will be born into this world without a father. I assure you, this child will be the next ruler of the kingdom of Ironforge."},
    [12548]={name="Magni's Will",quality=3,ilvl=60,reqLevel=50,sourceType="quest_reward",instructions="Reward from the quest 'The Princess's Surprise'. Pick it over the other reward choices.",zone="Blackrock Depths",questName="The Princess's Surprise",lore="Thaurissan was a great and honorable dwarf. You ruined my life and the life of my unborn child! Return to Ironforge and tell my father that the heir to the Kingdom of Ironforge will be a Dark Iron dwarf.",proc="Equip: Improves your chance to get a critical strike by 1.0%."},
    [12552]={name="Blisterbane Wrap",quality=3,ilvl=55,reqLevel=50,sourceType="world_drop",instructions="World drop around level 48-56."},
